/* The early-warning model's features and evaluation. See titra/risk.h. */
#include "titra/risk.h"

#include <math.h>
#include <string.h>

#include "titra/quality.h"

#define DIP_BELOW 85
#define DIP_MIN_S 10
#define NO_DIP_CAP_S 3600
#define ROOM_AIR_PM 211

/* The trained trees: risk_model.inc is generated by scripts/train_risk.py. */
#include "risk_model.inc"

void tr_features(const tf_second_t *ring, int cap, int head, int n, double out[TR_N_FEATURES]) {
    memset(out, 0, sizeof(double) * TR_N_FEATURES);
    out[2] = 100.0;
    out[12] = NO_DIP_CAP_S;
    if (ring == NULL || cap <= 0 || n <= 0) return;
    if (n > cap) n = cap;
    if (head < 0 || head >= cap) head = 0;

    const int long_n = n < TR_WINDOW_LONG ? n : TR_WINDOW_LONG;
    const int short_n = n < TR_WINDOW_SHORT ? n : TR_WINDOW_SHORT;
    const int long_start = n - long_n;
    const int short_start = n - short_n;
    const int third = short_n / 3;

    double sum = 0.0, sq = 0.0, fsum = 0.0, fsq = 0.0, first = 0.0, last = 0.0;
    int valid = 0, below91 = 0, below85 = 0, above = 0, on_o2 = 0, answered = 0, first_n = 0, last_n = 0;
    int dips_short = 0, dips_long = 0, run = 0, seconds_since = NO_DIP_CAP_S;

    for (int i = long_start; i < n; i++) {
        const tf_second_t *s = &ring[(head + i) % cap];
        const int ok = s->spo2 >= 0 && s->status == TC_SAMPLE_VALID;
        const int in_short = i >= short_start;
        if (ok && s->spo2 < DIP_BELOW) {
            run++;
            if (run == DIP_MIN_S) {
                dips_long++;
                if (in_short) dips_short++;
            }
            if (run >= DIP_MIN_S) seconds_since = 0;
        } else {
            run = 0;
            if (seconds_since < NO_DIP_CAP_S) seconds_since++;
        }
        if (!in_short) continue;
        const int fio2 = s->fio2_pm;
        if (fio2 >= 0) {
            const double f = fio2 / 1000.0;
            fsum += f;
            fsq += f * f;
            answered++;
            if (i < short_start + third) {
                first += f;
                first_n++;
            } else if (i >= n - third) {
                last += f;
                last_n++;
            }
        }
        if (!ok) continue;
        const double v = s->spo2;
        sum += v;
        sq += v * v;
        valid++;
        if (s->spo2 < 91) below91++;
        if (s->spo2 < 85) below85++;
        if (out[2] > v) out[2] = v;
        if (fio2 > ROOM_AIR_PM) {
            on_o2++;
            if (s->spo2 > 95) above++;
        }
    }
    if (valid > 0) {
        const double mean = sum / valid;
        out[0] = mean;
        const double var = sq / valid - mean * mean;
        out[1] = var > 0.0 ? sqrt(var) : 0.0;
        out[3] = 100.0 * below91 / valid;
        out[4] = 100.0 * below85 / valid;
    }
    out[5] = dips_short;
    out[6] = dips_long;
    if (answered > 0) {
        const double fmean = fsum / answered;
        out[7] = fmean;
        const double fvar = fsq / answered - fmean * fmean;
        out[9] = fvar > 0.0 ? sqrt(fvar) : 0.0;
    }
    if (first_n > 0 && last_n > 0) out[8] = last / last_n - first / first_n;
    if (on_o2 > 0) out[10] = 100.0 * above / on_o2;
    out[11] = 100.0 * (short_n - valid) / short_n;
    out[12] = seconds_since;
}

double tr_score(const double features[TR_N_FEATURES]) {
    double raw = RISK_BASE;
    for (int t = 0; t < RISK_TREES; t++) {
        int node = RISK_ROOT[t];
        /* Each step goes to a child, and a tree has at most RISK_DEPTH levels, so this loop is bounded. */
        for (int d = 0; d < RISK_DEPTH + 1 && RISK_FEATURE[node] >= 0; d++) {
            node = features[RISK_FEATURE[node]] <= RISK_THRESHOLD[node] ? RISK_LEFT[node] : RISK_RIGHT[node];
        }
        raw += RISK_VALUE[node];
    }
    return 1.0 / (1.0 + exp(-raw));
}

int tr_percent(const tf_second_t *ring, int cap, int head, int n) {
    double f[TR_N_FEATURES];
    tr_features(ring, cap, head, n, f);
    return (int)(tr_score(f) * 100.0 + 0.5);
}

int tr_tree_count(void) { return RISK_TREES; }
int tr_max_depth(void) { return RISK_DEPTH; }
